  if(runtime.status==='PAUSED')return <Shell onBack={exitLesson}><Text style={s.title}>已暫停</Text><Source runtime={runtime}/><Primary label="繼續"onPress={async()=>{const now=new Date().toISOString(),next=resumeLessonSessionV1(runtime,now);await persist(next);const adapted=adaptLearnerEventToPedagogyV1({id:uid('resume'),type:'RESUMED',occurredAt:now,support:next.blockState?.supportLevel??'NONE',observationIds:[]});await chooseBlock(next,adapted.event)}}/><Secondary label="離開練習" onPress={()=>void exitLesson()}/></Shell>;
  if(correction)return <Shell onBack={exitLesson}><Text style={s.kicker}>先確認你的意思</Text><Text style={s.title}>你原本想表達什麼？</Text><TextInput value={correction}onChangeText={setCorrection}multiline placeholder="可以用中文或英文告訴我"style={s.input}/><Text style={s.body}>你的原句會保留；更新理解不會建立學習證據。</Text><Primary label="更新我的意思"onPress={async()=>{const next=correctInterpretationStage4V4(runtime,correction);await persist(next);setCorrection('');const adapted=adaptLearnerEventToPedagogyV1({id:next.observations.at(-1)?.id??uid('source'),type:'SOURCE_CLARIFIED',occurredAt:new Date().toISOString(),support:next.blockState?.supportLevel??'NONE',observationIds:next.observations.slice(-1).map(item=>item.id)});await chooseBlock(next,adapted.event)}}/><Secondary label="取消"onPress={()=>setCorrection('')}/></Shell>;
  const writingWork=hydrateWritingWorkV1(runtime),translationWork=hydrateTranslationWorkV1(runtime),activeFreshTask=writingWork?.phase==='FRESH_WRITING'?writingWork.freshTask:undefined,activeFreshTranslationTask=translationWork?.phase==='FRESH_TRANSLATION'?translationWork.freshTask:undefined,activeTranslationSource=activeFreshTranslationTask?.sourceText??translationWork?.sourceContext.sourceText??runtime.artifact.chineseSource,readingSource=runtime.readingReview?`${runtime.readingReview.passage}\n\n${runtime.readingReview.question}`:undefined;const rawWorkspaceVM=projectAdaptiveWorkspaceV4({runtime,draft:text,sourceMeaning:readingSource??activeFreshTask?.promptText??activeTranslationSource}),workspaceVM=rawWorkspaceVM?withLearnerLessonExperienceV1({vm:rawWorkspaceVM,runtime,productMode:runtimeProductContext.productMode,timeRemainingMinutes:tutorTimeRemainingMinutesV1(runtime)}):undefined;
